package com.worklyn.modules.leave.model;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.CompoundIndex;import org.springframework.data.mongodb.core.mapping.Document;
@Document(collection="leave_balances") @CompoundIndex(name="employee_year_unique",def="{'employeeId':1,'year':1}",unique=true)
public class LeaveBalance {
 @Id private String id; private String employeeId; private Integer year; private int casualLeaveAvailable=12; private int sickLeaveAvailable=10; private int earnedLeaveAvailable=15; private int casualLeaveUsed; private int sickLeaveUsed; private int earnedLeaveUsed;
 public String getId(){return id;} public void setId(String v){id=v;} public String getEmployeeId(){return employeeId;} public void setEmployeeId(String v){employeeId=v;} public Integer getYear(){return year;} public void setYear(Integer v){year=v;} public int getCasualLeaveAvailable(){return casualLeaveAvailable;} public void setCasualLeaveAvailable(int v){casualLeaveAvailable=v;} public int getSickLeaveAvailable(){return sickLeaveAvailable;} public void setSickLeaveAvailable(int v){sickLeaveAvailable=v;} public int getEarnedLeaveAvailable(){return earnedLeaveAvailable;} public void setEarnedLeaveAvailable(int v){earnedLeaveAvailable=v;} public int getCasualLeaveUsed(){return casualLeaveUsed;} public void setCasualLeaveUsed(int v){casualLeaveUsed=v;} public int getSickLeaveUsed(){return sickLeaveUsed;} public void setSickLeaveUsed(int v){sickLeaveUsed=v;} public int getEarnedLeaveUsed(){return earnedLeaveUsed;} public void setEarnedLeaveUsed(int v){earnedLeaveUsed=v;}
 public int available(LeaveType t){return switch(t){case CASUAL->casualLeaveAvailable;case SICK->sickLeaveAvailable;case EARNED->earnedLeaveAvailable;case UNPAID->Integer.MAX_VALUE;case MATERNITY,PATERNITY->0;};}
 public void deduct(LeaveType t,int n){switch(t){case CASUAL->{casualLeaveAvailable-=n;casualLeaveUsed+=n;}case SICK->{sickLeaveAvailable-=n;sickLeaveUsed+=n;}case EARNED->{earnedLeaveAvailable-=n;earnedLeaveUsed+=n;}case UNPAID->{}case MATERNITY,PATERNITY->throw new IllegalArgumentException("No configured balance for "+t);}}
 public void credit(LeaveType t,int n){switch(t){case CASUAL->{casualLeaveAvailable+=n;casualLeaveUsed=Math.max(0,casualLeaveUsed-n);}case SICK->{sickLeaveAvailable+=n;sickLeaveUsed=Math.max(0,sickLeaveUsed-n);}case EARNED->{earnedLeaveAvailable+=n;earnedLeaveUsed=Math.max(0,earnedLeaveUsed-n);}case UNPAID->{}case MATERNITY,PATERNITY->{}}}
}
